"""One-file-per-type Telegram Bot API model package.

The package intentionally keeps the legacy ``models.py`` facade as the
compatibility import surface while exposing every Telegram type here.
"""

from __future__ import annotations

import importlib
import pkgutil
import sys

_PACKAGE = __name__

for _module_info in pkgutil.iter_modules(__path__):
    _name = _module_info.name
    if _name == "__init__" or _name.startswith("_"):
        continue
    importlib.import_module(f"{_PACKAGE}.{_name}")

for _name in ("_aliases", "_helpers"):
    importlib.import_module(f"{_PACKAGE}.{_name}")

_namespace = {}
for _module_name, _module in list(sys.modules.items()):
    if _module_name.startswith(_PACKAGE + "."):
        for _key, _value in vars(_module).items():
            if not _key.startswith("__"):
                _namespace[_key] = _value

globals().update({k: v for k, v in _namespace.items() if not k.startswith("_")})
for _key, _value in _namespace.items():
    if _key.startswith("_") and _key not in {
        "_PACKAGE", "_module_info", "_name", "_module_name", "_module",
        "_key", "_value", "_namespace",
    }:
        globals()[_key] = _value

for _module_name, _module in list(sys.modules.items()):
    if _module_name.startswith(_PACKAGE + "."):
        _module.__dict__.update(_namespace)

